// Created: 2026-11-20

// The raw-body helper feeds /api/md, the batch and job routes and
// /llms-full.txt. A checkout with CRLF line endings (Windows, or an editor
// that rewrote the file) must not leak the YAML block into those bodies.

import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/source", () => ({ source: { getPages: () => [] } }));

import { readDocBody, stripFrontmatter } from "@/lib/docs-content";

describe("stripFrontmatter", () => {
	it("strips an LF frontmatter block", () => {
		expect(stripFrontmatter("---\ntitle: Example\n---\n# Body\n")).toBe("# Body\n");
	});

	it("strips a CRLF frontmatter block", () => {
		expect(stripFrontmatter("---\r\ntitle: Example\r\n---\r\n# Body\r\n")).toBe(
			"# Body\r\n",
		);
	});

	it("leaves a body without frontmatter unchanged", () => {
		const body = "# Body\r\n\r\n---\r\nnot: frontmatter\r\n---\r\n";
		expect(stripFrontmatter(body)).toBe(body);
	});

	it("leaves an unterminated fence unchanged", () => {
		const raw = "---\r\ntitle: Example\r\n# Body\r\n";
		expect(stripFrontmatter(raw)).toBe(raw);
	});

	it("stops at the first closing fence", () => {
		expect(
			stripFrontmatter("---\r\ntitle: Example\r\n---\r\n# Body\r\n---\r\nmore\r\n"),
		).toBe("# Body\r\n---\r\nmore\r\n");
	});
});

describe("readDocBody", () => {
	let root: string | undefined;

	afterEach(async () => {
		vi.restoreAllMocks();
		if (root) await fs.rm(root, { recursive: true, force: true });
		root = undefined;
	});

	it("returns only the body of a CRLF page on disk", async () => {
		root = await fs.mkdtemp(path.join(os.tmpdir(), "docs-content-"));
		await fs.mkdir(path.join(root, "content/docs/guides"), { recursive: true });
		await fs.writeFile(
			path.join(root, "content/docs/guides/example.mdx"),
			"---\r\ntitle: Example\r\ndescription: Demo\r\n---\r\n\r\n# Body\r\n\r\nText.\r\n",
		);
		vi.spyOn(process, "cwd").mockReturnValue(root);

		expect(await readDocBody(["guides", "example"])).toBe("# Body\r\n\r\nText.");
	});
});
